<script setup lang="ts">
import { computed } from 'vue';

interface Props {
  data: {
    headers: string[] | string;
    rows: string[][] | string;
    animation?: string;
    padding?: any;
    paddingMd?: any;
    paddingXl?: any;
  }
}

const props = defineProps<Props>();

// تبدیل داده‌ها از رشته به آرایه (در صورتی که به صورت JSON ذخیره شده باشند)
const tableHeaders = computed(() => {
  return typeof props.data.headers === 'string'
    ? JSON.parse(props.data.headers)
    : props.data.headers;
});

const tableRows = computed(() => {
  return typeof props.data.rows === 'string'
    ? JSON.parse(props.data.rows)
    : props.data.rows;
});

// مدیریت پدینگ‌ها (مشابه سیستم قبلی شما)
const customStyle = computed(() => {
  return {
    ...props.data.padding,
    // در اینجا می‌توانید منطق مدیا کوئری را برای paddingMd و paddingXl اضافه کنید
    // یا کلاس‌های شرطی وویتیفای را به المان والد بدهید
  };
});
</script>

<template>
  <div
    :class="['table-container', data.animation]"
    :style="customStyle"
  >
    <v-table class="custom-dynamic-table border">
      <thead>
      <tr>
        <th
          v-for="(header, index) in tableHeaders"
          :key="index"
          class="text-right font-weight-bold bg-grey-lighten-4"
        >
          {{ header }}
        </th>
      </tr>
      </thead>
      <tbody>
      <tr v-for="(row, rowIndex) in tableRows" :key="rowIndex">
        <td
          v-for="(cell, cellIndex) in row"
          :key="cellIndex"
          class="text-right"
        >
          {{ cell }}
        </td>
      </tr>
      </tbody>
    </v-table>
  </div>
</template>

<style scoped>
.table-container {
  width: 100%;
  overflow-x: auto;
}

.custom-dynamic-table {
  width: 100%;
  border-collapse: collapse;
}

/* استایل برای پشتیبانی از فارسی */
:deep(.v-table__wrapper) {
  direction: rtl;
}

.font-weight-bold {
  color: #333;
}

/* افکت Hover برای سطرها */
tbody tr:hover {
  background-color: #f9f9f9;
  transition: background-color 0.2s ease;
}
</style>
